'use strict';
// Entirely synthetic. No fetch, network, process control, storage, or app bridge.
const ICONS = {
  port:'<path d="M8 3v5m8-5v5M6 8h12v4a6 6 0 0 1-12 0V8Zm6 10v3"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m9 12 2 2 4-4"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  activity:'<path d="M2 12h4l3-7 5 14 3-7h5"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
  monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',
  folder:'<path d="M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11H3V7Z"/>',
  gear:'<path d="m9 3-.6 2.4-2 .9L4 6l-2 4 2 1.5v2L2 15l2 4 2.4-.3 2 .9L9 22h5l.6-2.4 2-.9L19 19l2-4-2-1.5v-2l2-1.5-2-4-2.4.3-2-.9L14 3H9Z"/><circle cx="11.5" cy="12.5" r="3"/>',
  pause:'<path d="M8 5v14M16 5v14"/>',
  stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',
  copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
  command:'<path d="M8 8V5a3 3 0 1 0-3 3h14a3 3 0 1 0-3-3v14a3 3 0 1 0 3-3H5a3 3 0 1 0 3 3V8Z"/>',
  globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
  warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v4m0 3v1"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
  terminal:'<path d="m5 7 5 5-5 5m8 0h6"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
  panel:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M15 4v16"/>',
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] || ICONS.port}</svg>`;
const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records = [
  {port:3000,name:'Studio Web',process:'node',pid:4812,project:'Atlas',bind:'127.0.0.1',cpu:'1.8',memory:'142',symbol:'N',path:'/opt/homebrew/bin/node',uptime:'2h 14m'},
  {port:5173,name:'Admin UI',process:'vite',pid:5290,project:'Atlas',bind:'127.0.0.1',cpu:'0.4',memory:'86',symbol:'V',path:'/opt/homebrew/bin/node',uptime:'48m'},
  {port:8000,name:'Python API',process:'python3',pid:6124,project:'Atlas',bind:'0.0.0.0',cpu:'2.1',memory:'118',symbol:'Py',path:'/opt/homebrew/bin/python3',uptime:'1h 32m'},
  {port:5432,name:'PostgreSQL',process:'postgres',pid:1042,project:'Data',bind:'127.0.0.1',cpu:'0.2',memory:'64',symbol:'Pg',path:'/opt/homebrew/bin/postgres',uptime:'6h 02m'},
  {port:6379,name:'Redis',process:'redis-server',pid:1077,project:'Data',bind:'127.0.0.1',cpu:'0.1',memory:'12',symbol:'R',path:'/opt/homebrew/bin/redis-server',uptime:'6h 02m'},
  {port:8080,name:'Docs preview',process:'http-server',pid:7341,project:'Tools',bind:'127.0.0.1',cpu:'0.0',memory:'23',symbol:'H',path:'/opt/homebrew/bin/node',uptime:'12m'},
  {port:9229,name:'Node inspector',process:'node',pid:4812,project:'Tools',bind:'127.0.0.1',cpu:'1.8',memory:'142',symbol:'N',path:'/opt/homebrew/bin/node',uptime:'2h 14m'},
  {port:4200,name:'Worker metrics',process:'worker',pid:8051,project:'Local',bind:'127.0.0.1',cpu:'0.3',memory:'31',symbol:'W',path:'/usr/local/bin/worker',uptime:'32m'},
  {port:11434,name:'Local models',process:'model-server',pid:2816,project:'Local',bind:'0.0.0.0',cpu:'0.1',memory:'328',symbol:'M',path:'/usr/local/bin/model-server',uptime:'3h 41m'},
];
const directions = {
  orbit:{number:'07',name:'Orbit',tag:'Everything has a place.',description:'A local observatory in graphite and copper. Listeners sit around a focused endpoint, with process identity and deliberate actions in a separate inspector. The map is a spatial selection index, not network topology.',tradeoff:'The most expressive direction. Keep the equivalent list view for dense scanning and spatial accessibility.'},
  shell:{number:'05',name:'Shell',tag:'Your workspace. At the prompt.',description:'A terminal-native composition: command output, a manual-page inspector, and an editable prompt with fixed preview commands.',tradeoff:'Best for terminal fluency. Keep clickable controls and discoverable help alongside the prompt.'},
  play:{number:'06',name:'Play',tag:'Serious tools can have a little soul.',description:'A tactile local workspace with colored service tiles, rounded navigation, and a friendly process inspector. Personality without obscuring consequences.',tradeoff:'Best for approachability and recognition. Lower information density than a table.'},
  instrument:{number:'01',name:'Instrument',tag:'Quiet. Precise. Familiar.',description:'A restrained macOS workbench. Scan the table, select a listener, inspect it in place. One accent, stable columns, actions kept close to their target.',tradeoff:'Best everyday foundation. Higher information density without the dashboard noise.'},
  relay:{number:'02',name:'Relay',tag:'Built for the people who live here.',description:'An operational console with horizontal navigation, a dense monospace table, and a persistent selection tray. Less chrome; more useful rows.',tradeoff:'Best for CLI-minded power users. Deliberately more technical and less approachable.'},
  fieldwork:{number:'03',name:'Fieldwork',tag:'A workspace, not a list of numbers.',description:'Project-first organization, warm paper, editorial type. Atlas, Data, and Tools are the entry points; ports become the supporting detail.',tradeoff:'Best for multiple projects. Project grouping is a proposed feature, not existing discovery.'},
  focus:{number:'04',name:'Focus',tag:'Understand one thing completely.',description:'A master list and a focused process canvas. Follow a listener from interface to endpoint to executable, with deliberate controls and minimal competing UI.',tradeoff:'Best inspection experience. Fewer listeners visible at once; weaker for bulk scanning.'},
};
const params = new URLSearchParams(location.search);
const state = {direction:directions[params.get('direction')] ? params.get('direction') : 'instrument',view:'ports',selected:3000,filter:'all',query:'',monitor:true,inspector:true,compact:false,project:'all',comparison:params.get('compare') === '1',lastCheck:'5 seconds ago',intent:null};
state.surface=params.get('surface')==='menubar'?'menubar':'window';
state.menuPane='listeners';
state.menuOpen=true;
const embedded = params.get('embed') === '1';
if (embedded) document.body.classList.add('embed');
const $ = selector => document.querySelector(selector);
const selected = () => records.find(p => p.port === state.selected) || records[0];
function visibleRecords(){return records.filter(p => (state.filter==='all'||(state.filter==='lan'?p.bind==='0.0.0.0':p.bind==='127.0.0.1')) && (state.project==='all'||p.project===state.project) && `${p.port} ${p.name} ${p.process} ${p.pid} ${p.project} ${p.bind}`.toLowerCase().includes(state.query.toLowerCase()));}
const traffic = () => '<div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div>';
const brand = () => `<div class="brand"><span class="brand-icon">${icon('port')}</span>PortPilot</div>`;
const sections = [{key:'ports',name:'Ports',icon:'port',count:9},{key:'security',name:'Observations',icon:'shield',count:2},{key:'schedules',name:'Schedules',icon:'clock',count:4},{key:'activity',name:'Activity',icon:'activity'}];
function nav(mode='sidebar'){return sections.map(s=>`<button class="${mode==='rail'?'rail-button':mode==='top'?'':'nav-button'} ${state.view===s.key?'active':''}" data-view="${s.key}" aria-label="${s.name}" ${state.view===s.key?'aria-current="page"':''} title="${s.name}">${mode==='top'?'':icon(s.icon)}${mode==='rail'?'':`<span>${s.name}</span>${mode==='top'?'':`<span class="count">${s.count||''}</span>`}`}</button>`).join('');}
function sidebar(){return `<aside class="sidebar">${brand()}<div class="side-heading">WORKSPACE</div><nav class="nav" aria-label="Workspace">${nav()}</nav><div class="side-divider"></div><div class="side-heading">PROJECTS <span class="muted">· concept</span></div><nav class="nav" aria-label="Example projects">${['Atlas','Data','Tools','Local'].map((p,i)=>`<button class="nav-button" data-project="${p}"><span class="project-dot" style="opacity:${.85-i*.15}"></span>${p}<span class="count">${records.filter(r=>r.project===p).length}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-button" data-action="command">${icon('command')}Commands<kbd style="margin-left:auto">⌘ K</kbd></button><button class="nav-button" data-action="notes">${icon('gear')}Direction notes</button><div class="profile"><span class="avatar">D</span><span>Developer<br><small class="muted">Local user session</small></span></div></div></aside>`;}
function status(){return `<div class="window-status"><span class="flex gap">${icon('monitor')}This Mac</span><span>·</span><span>${state.monitor?'Latest example snapshot · '+state.lastCheck:'Monitoring paused · last example retained'}</span><span class="spacer"></span><span class="hide-small">User-level visibility</span><span class="mono">SAMPLE DATA / NO OS ACCESS</span></div>`;}
function windowBar(mode='normal'){return `<div class="window-bar">${traffic()}${mode==='relay'?`${brand()}<nav class="relay-nav" aria-label="Workspace">${nav('top')}</nav>`:`<span class="window-title">PortPilot <span class="muted">/ ${state.view==='ports'?'Workspace':sections.find(s=>s.key===state.view).name}</span></span>`}<span class="spacer"></span><span class="machine">${icon('monitor')}This Mac <span class="muted">⌄</span></span>${mode==='relay'?'':`<button class="icon-button" data-action="command" aria-label="Open command palette" title="Commands · ⌘ K">${icon('command')}</button>`}</div>`;}
function heading(title,subtitle,eyebrow=''){return `<header class="page-heading"><div>${eyebrow?`<div class="eyebrow muted">${eyebrow}</div>`:''}<h1>${title}</h1><p>${subtitle}</p></div><div class="status-line"><span class="dot"></span>${state.monitor?'Snapshot · '+state.lastCheck:'Paused'}</div></header>`;}
function searchTools(narrow=false){return `<div class="search-tools"><label class="search">${icon('search')}<input type="search" id="search" aria-label="Search ports, processes, or projects" placeholder="${narrow?'Search listeners…':'Find a port, process, or project…'}" value="${escapeHTML(state.query)}"><kbd>/</kbd></label>${narrow?'':`<button class="toolbar-button" data-action="refresh" title="Refresh example snapshot">${icon('refresh')}Refresh</button>${state.direction==='instrument'?`<button class="icon-button" data-action="inspector" aria-label="Toggle inspector" title="Toggle inspector">${icon('panel')}</button>`:''}`}</div>`;}
function filters(){return `<div class="filter-row" role="group" aria-label="Listener scope">${[['all','All listeners',9],['local','Local only',7],['lan','LAN exposed',2]].map(([key,label,n])=>`<button class="filter-chip ${state.filter===key?'active':''}" data-filter="${key}" aria-label="${label}" aria-pressed="${state.filter===key}">${state.direction==='focus'?{all:'All',local:'Local',lan:'LAN'}[key]:label}<span>${n}</span></button>`).join('')}${state.project!=='all'?`<button class="filter-chip active" data-project="all">${state.project} ×</button>`:''}<span class="spacer"></span>${state.direction==='relay'?`<button class="filter-chip" data-action="density">${state.compact?'Comfortable':'Compact'} ↕</button>`:''}</div>`;}
function table(){const items=visibleRecords();return `<div class="table-scroll">${items.length?`<table aria-label="Example listening processes"><thead><tr><th>Port ↓</th><th>Process</th><th class="table-pid">PID</th><th class="table-bind">Interface</th><th class="table-cpu">CPU</th><th>Scope</th></tr></thead><tbody>${items.map(p=>`<tr data-port="${p.port}" tabindex="0" aria-label="Inspect ${p.name} on port ${p.port}" aria-selected="${state.selected===p.port}" class="${state.selected===p.port?'selected':''}"><td class="port-cell">${p.port}</td><td><div class="process"><span class="process-icon">${p.symbol}</span><span class="process-text"><b>${p.name}</b><small>${p.project} / ${p.process}</small></span></div></td><td class="table-pid mono muted">${p.pid}</td><td class="table-bind mono muted">${p.bind}</td><td class="table-cpu mono muted">${p.cpu}%</td><td><span class="badge ${p.bind==='0.0.0.0'?'warning':''}">${p.bind==='0.0.0.0'?'LAN exposed':'Local only'}</span></td></tr>`).join('')}</tbody></table>`:`<div class="empty">No listeners match this view.<br><button data-action="clear">Clear search and filters</button></div>`}</div>`;}
function actions(p){return `<button class="toolbar-button" data-action="proxy">${icon('arrow')}Quick Proxy</button><button class="danger-button" data-action="stop" aria-label="Request stop for ${p.name}">${icon('stop')}Stop process</button>`;}
function inspector(){const p=selected();return `<aside class="inspector" aria-label="Selected process inspector"><div class="inspector-heading between">PROCESS INSPECTOR <span class="badge">TCP</span></div><div class="process-emblem">${p.symbol}</div><h2>${p.name}</h2><p class="inspector-subtitle">${p.process} <span class="muted">· PID ${p.pid}</span></p><div class="endpoint"><span>${p.bind}:${p.port}</span><button class="icon-button" data-action="copy" aria-label="Copy selected address">${icon('copy')}</button></div><section class="inspector-section"><h3>Identity</h3><div class="property"><span>User</span><span>developer</span></div><div class="property"><span>Project</span><span>${p.project} <small class="muted">(example)</small></span></div><div class="property"><span>Running for</span><span class="mono">${p.uptime}</span></div><div class="property"><span>Interface scope</span><span>${p.bind==='0.0.0.0'?'All IPv4 interfaces':'IPv4 loopback'}</span></div><div class="path">${p.path}</div></section><section class="inspector-section"><div class="between"><h3>Resource sample</h3><span class="muted" style="font-size:9px">ILLUSTRATIVE / 60s</span></div><div class="between"><span class="metric">${p.cpu}<small> % CPU</small></span><span class="mono muted" style="font-size:10px">${p.memory} MB</span></div><svg class="sparkline" viewBox="0 0 220 40" preserveAspectRatio="none" aria-label="Illustrative CPU sample"><path class="baseline" d="M0 35h220"/><path d="M0 31h10l5-3 7 2 8-5 5 4 10-2 8 3 7-12 5 8 7-2 6 5 10-3 7-7 6 5 7-2 5 6 8-4 10 1 7-17 6 13 6-3 8 4 6-2 6 4 7-3h15l5-9 5 6 7 2h17"/></svg></section><div class="inspector-actions">${actions(p)}</div></aside>`;}
function security(){return heading('Observations','Two things worth a look. These are heuristics, not malware verdicts.')+`<div class="section-body"><div class="between"><div class="status-line"><span class="dot"></span>${state.monitor?'Example snapshot complete':'Monitoring paused; observations may be stale'}</div><button class="toolbar-button" data-action="monitor">${icon('pause')}${state.monitor?'Pause monitoring':'Resume monitoring'}</button></div><article class="observation"><div class="observation-top">${icon('warning')}<h3>Python API accepts connections on all IPv4 interfaces</h3><span class="spacer"></span><span class="badge warning">Review scope</span></div><p><span class="mono">0.0.0.0:8000</span> may be reachable from your LAN, subject to routing and firewall rules. If this is a development-only API, consider binding the service to loopback.</p><div class="between"><span class="mono muted" style="font-size:10px">python3 · PID 6124 · developer</span><button class="toolbar-button" data-inspect="8000">Inspect listener ${icon('arrow')}</button></div></article><article class="observation"><div class="observation-top">${icon('info')}<h3>A Node debugger is listening</h3><span class="spacer"></span><span class="badge">Informational</span></div><p>The debugger on <span class="mono">127.0.0.1:9229</span> is local to this Mac. Close it when you're finished debugging. Its presence alone doesn't indicate malicious activity.</p><div class="between"><span class="mono muted" style="font-size:10px">node · PID 4812 · developer</span><button class="toolbar-button" data-inspect="9229">Inspect listener ${icon('arrow')}</button></div></article><div class="note">Periodic, user-level snapshots can miss short-lived or permission-hidden activity. An alert list annotates observations; it doesn't block network traffic. Example findings on this screen are synthetic.</div></div>`;}
const jobs=[{name:'Workspace backup',command:'0 18 * * *   ~/scripts/backup-workspace.sh',next:'Today, 18:00',last:'Completed · yesterday'}, {name:'Refresh local indexes',command:'*/30 * * * *   ~/scripts/index.sh',next:'Today, 14:30',last:'Completed · 14:00'}, {name:'Rotate development logs',command:'0 9 * * *   ~/scripts/rotate-logs.sh',next:'Tomorrow, 09:00',last:'Completed · 09:00'}, {name:'Clean build cache',command:'0 10 * * 1   ~/scripts/clean-cache.sh',next:'Monday, 10:00',last:'Not run this session'}];
function schedules(){return heading('Schedules','Know what runs next, and what happened last.')+`<div class="section-body">${jobs.map((j,i)=>`<article class="schedule">${icon('clock')}<div><h3>${j.name}</h3><p>${j.command}</p></div><div class="schedule-time">${j.next}<br><small>${j.last}</small></div><button class="icon-button" data-run="${i}" aria-label="Simulate running ${j.name}" title="Run now · simulation">${icon('arrow')}</button></article>`).join('')}<div class="note">Run Now executes shell code in the real product. This prototype only previews that interaction; it cannot read or change a crontab.</div></div>`;}
function activity(){return heading('Activity','A readable trail of observations and deliberate actions.')+`<div class="section-body">${[['14:24:05','Connection snapshot completed','9 listening endpoints observed. User-level discovery.'],['14:23:58','Python API listener appeared','Port 8000 · all IPv4 interfaces · observation added.'],['14:23:21','Admin UI listener appeared','Port 5173 · IPv4 loopback · PID 5290.'],['14:22:09','Monitoring resumed','Session learning continues from complete snapshots.'],['14:00:00','Index refresh completed','Synthetic schedule history · exit status 0.']].map(([t,h,d])=>`<article class="event"><time>${t}</time><div><h3 style="font-size:11px;font-weight:550">${h}</h3><p>${d}</p></div></article>`).join('')}<div class="note">Illustrative activity only. No real process, connection, or cron history is accessed by this prototype.</div></div>`;}
function alternateView(){return state.view==='security'?security():state.view==='schedules'?schedules():activity();}
function instrument(){return `${windowBar()}<div class="body-layout">${sidebar()}<section class="content">${state.view==='ports'?heading('Listening ports','What’s running on this Mac, at a glance.')+searchTools()+filters()+table():alternateView()}</section>${state.view==='ports'&&state.inspector?inspector():''}</div>${status()}`;}
function relay(){const p=selected();return `${windowBar('relay')}<section class="content">${state.view==='ports'?heading('LISTENING_ENDPOINTS','This Mac / user session / TCP')+`<div class="relay-summary"><div class="relay-metric"><span>Listening</span><b>09<small>endpoints</small></b></div><div class="relay-metric"><span>Loopback</span><b>07<small>local only</small></b></div><div class="relay-metric"><span>All interfaces</span><b style="color:var(--amber)">02<small>review scope</small></b></div><div class="relay-metric"><span>Observations</span><b>02<small>heuristic</small></b></div></div>`+searchTools()+filters()+table():alternateView()}</section>${state.view==='ports'?`<section class="selection-tray" aria-label="Selected process"><div class="tray-title"><div class="eyebrow muted">SELECTED / ${p.port}</div><h3>${p.process} <span class="muted">${p.pid}</span></h3></div><div class="property"><span>INTERFACE</span><span>${p.bind}:${p.port}</span></div><div class="property"><span>OWNER / UPTIME</span><span>developer / ${p.uptime}</span></div><div class="property"><span>CPU / MEMORY</span><span>${p.cpu}% / ${p.memory} MB</span></div><div class="inspector-actions">${actions(p)}</div></section>`:''}${status()}`;}
function fieldwork(){return `${windowBar()}<div class="body-layout">${sidebar()}<section class="content">${state.view==='ports'?heading('Local workspace.','Four projects. Nine listeners. Room to think.','FRIDAY, 23 OCTOBER')+`<div class="search-tools"><label class="search">${icon('search')}<input type="search" id="search" aria-label="Search ports, processes, or projects" placeholder="Find something running…" value="${escapeHTML(state.query)}"><kbd>/</kbd></label><span style="flex:none">${filters()}</span></div><div class="field-body"><div class="project-grid">${['Atlas','Data','Tools','Local'].map(name=>{const items=visibleRecords().filter(p=>p.project===name);return items.length?`<section class="project-card"><div class="project-heading"><span class="flex"><span class="folder">${icon('folder')}</span><h2>${name}</h2></span><small>${items.length} ${items.length===1?'listener':'listeners'}</small></div>${items.map(p=>`<button class="project-row ${p.port===state.selected?'selected':''}" data-port="${p.port}" aria-label="Inspect ${p.name} on port ${p.port}"><span class="port">:${p.port}</span><span class="project-name">${p.name}</span>${p.bind==='0.0.0.0'?'<span class="badge warning">LAN</span>':`<span class="spacer"></span><span class="dot" style="opacity:.5"></span>`}</button>`).join('')}</section>`:'';}).join('')}${visibleRecords().length?'':`<div class="empty">No listeners match.<br><button data-action="clear">Clear filters</button></div>`}<div class="next-schedule">${icon('clock')}<div><h3>Next on the schedule</h3><p>Refresh local indexes <span class="mono">· 14:30</span></p></div><button class="text-button" style="margin:0 0 0 auto" data-view="schedules">View all ${icon('arrow')}</button></div></div><aside class="field-brief"><h2>On your radar.</h2><p class="brief-date">LATEST EXAMPLE / 14:24</p><div class="brief-item"><span class="badge warning">Review scope</span><h3>Two listeners on the LAN.</h3><p>Python API and Local models bind to all IPv4 interfaces.</p><button class="text-button" data-filter="lan">See listeners ${icon('arrow')}</button></div><div class="brief-item"><span class="eyebrow muted">SELECTED LISTENER</span><h3>${selected().name}</h3><p class="mono">${selected().bind}:${selected().port}</p><p style="margin-top:7px">${selected().process} · PID ${selected().pid}<br>developer · ${selected().memory} MB</p><button class="text-button" data-action="details">Inspect process ${icon('arrow')}</button></div><div class="brief-item"><p>Project associations are a design proposal. They need explicit user assignment or a reliable discovery source.</p></div></aside></div>`:alternateView()}</section></div>${status()}`;}
function focus(){const p=selected();return `${windowBar()}<div class="body-layout"><nav class="focus-rail" aria-label="Workspace"><span class="brand-icon">${icon('port')}</span>${nav('rail')}<span class="spacer"></span><button class="rail-button" data-action="command" aria-label="Open commands">${icon('command')}</button><button class="rail-button" data-action="notes" aria-label="Direction notes">${icon('gear')}</button></nav>${state.view==='ports'?`<aside class="focus-list"><div class="focus-list-heading between"><div><h1>Listeners</h1><p>${visibleRecords().length} visible · this Mac</p></div><button class="icon-button" data-action="refresh" aria-label="Refresh example snapshot">${icon('refresh')}</button></div>${searchTools(true)}${filters()}${visibleRecords().map(p=>`<button class="focus-port ${p.port===state.selected?'selected':''}" data-port="${p.port}" aria-label="Inspect ${p.name} on port ${p.port}"><span class="process-icon">${p.symbol}</span><span><strong>${p.name}</strong><small>:${p.port} · ${p.process}</small></span><span class="arrow">${p.bind==='0.0.0.0'?'<span class="dot amber"></span>':icon('chevron')}</span></button>`).join('')||'<div class="empty">No matching listeners.<br><button data-action="clear">Clear filters</button></div>'}</aside><section class="focus-canvas" aria-label="Selected process details"><div class="focus-context">${icon('monitor')}This Mac ${icon('chevron')}${p.project} ${icon('chevron')}<span>${p.name}</span><span class="spacer"></span><span class="badge">TCP LISTENER</span></div><div class="focus-title"><div><h2>${p.name}</h2><p>${p.process} <span class="mono">· PID ${p.pid}</span> · running for ${p.uptime}</p></div><div class="process-emblem">${p.symbol}</div></div><div class="scope-note">${icon(p.bind==='0.0.0.0'?'warning':'info')}${p.bind==='0.0.0.0'?'All IPv4 interfaces. LAN reachability depends on routing and firewall rules.':'IPv4 loopback. This listener accepts connections from this Mac.'}</div><div class="connection-map" aria-label="Interface to listener to process relationship"><div class="map-node">${icon(p.bind==='0.0.0.0'?'globe':'monitor')}<b>${p.bind==='0.0.0.0'?'All interfaces':'This Mac'}</b><small>${p.bind==='0.0.0.0'?'IPv4 wildcard':'IPv4 loopback'}</small></div><div class="connector">${icon('arrow')}</div><div class="map-node listener">${icon('port')}<b>:${p.port}</b><small>${p.bind}</small></div><div class="connector">${icon('arrow')}</div><div class="map-node">${icon('terminal')}<b>${p.process}</b><small>PID ${p.pid}</small></div></div><p class="focus-map-label">Interface scope → listening endpoint → owning process<br>Relationship diagram · does not represent captured packet traffic</p><div class="focus-facts"><div class="fact-card"><span>CPU sample</span><b>${p.cpu}%</b></div><div class="fact-card"><span>Memory sample</span><b>${p.memory} MB</b></div><div class="fact-card"><span>OS user</span><b>developer</b></div></div><div class="focus-executable"><span>Executable</span><code>${p.path}</code><span class="spacer"></span><button class="icon-button" data-action="copy" aria-label="Copy selected address">${icon('copy')}</button></div><div class="focus-actions">${actions(p)}</div><p class="muted" style="font-size:9px;margin-top:14px;line-height:1.7">Process identity is rechecked before real control actions. A path is not a signature or an approval.</p></section>`:`<section class="content">${alternateView()}</section>`}</div>${status()}`;}
function render(){
  document.body.classList.toggle('compare-page',state.comparison);
  document.body.classList.toggle('menu-surface',state.surface==='menubar');
  document.querySelectorAll('[data-surface]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.surface===state.surface)));
  document.querySelectorAll('[data-direction]').forEach(b=>b.setAttribute('aria-pressed',String(!state.comparison&&b.dataset.direction===state.direction)));
  if(state.comparison){renderComparison();return;}
  const fn={instrument,relay,fieldwork,focus,shell,play,orbit}[state.direction];
  $('#stage').innerHTML=state.surface==='menubar'?renderMenubar():`<div class="window ${state.direction}" ${state.compact?'style="--row:30px"':''}>${fn()}</div>`;
  const d=directions[state.direction];
  $('#study-footer').innerHTML=`<div class="concept-title"><strong>${d.number} / ${d.name}${state.surface==='menubar'?' · menu bar':''}</strong>${d.tag}</div><p>${state.surface==='menubar'?menuDirections[state.direction]:d.description}<br><span style="color:#4e5760">${d.tradeoff}</span></p><p class="study-hint">Click a listener. Switch sections.<br>Search with / · Commands with ⌘ K<br>All controls are simulated.</p>`;
  document.title=`PortPilot — ${d.name} / interface study`;
}
function renderComparison(){
  const newest=params.get('set')==='new';
  const entries=Object.entries(directions).sort((a,b)=>a[1].number.localeCompare(b[1].number)).filter(([key])=>!newest||['shell','play'].includes(key));
  $('#stage').innerHTML=`<header class="comparison-heading"><div><div class="eyebrow muted">PORTPILOT / ${newest?'TWO NEW DIRECTIONS':'SEVEN POSSIBLE FUTURES'}</div><h1>${newest?'A little more character.':'Seven ways to feel at home.'}</h1><p>${state.surface==='menubar'?'The menu-bar app deserves the same care as the workspace.':'Explore the layout, select a listener, try the controls.'}</p></div><span class="badge">Interactive studies · synthetic data</span></header><section class="comparison-grid ${newest?'new-pair':''}">${entries.map(([key,d])=>{const url=new URL(location.href);url.search='';url.searchParams.set('direction',key);url.searchParams.set('embed','1');url.searchParams.set('surface',state.surface);return `<article class="comparison-card"><div class="mini-frame"><iframe src="${url.href}" title="${d.name} concept preview" tabindex="-1" loading="eager"></iframe><a href="?direction=${key}&surface=${state.surface}" data-direction="${key}" aria-label="Explore ${d.name}">Explore ${d.name} ↗</a></div><div class="comparison-caption"><span>${d.number}</span><div><h2>${d.name}</h2><p>${d.tag}<br>${state.surface==='menubar'?menuDirections[key]:d.tradeoff}</p></div></div></article>`;}).join('')}</section><div class="study-recommendation"><b>My take:</b> Shell should earn its terminal feel through useful commands. Play should make services easier to recognize. Pick a consistent everyday layout before wiring visual themes into the native app.</div>`;
  $('#study-footer').innerHTML='<p>Design prototypes · synthetic data · no OS access. Native app unchanged.</p>';
  document.title='PortPilot — compare interface directions';
  requestAnimationFrame(scalePreviews);
}
function scalePreviews(){document.querySelectorAll('.mini-frame').forEach(frame=>{const iframe=frame.querySelector('iframe');if(iframe)iframe.style.transform=`scale(${frame.clientWidth/(state.surface==='menubar'?480:1280)})`;});}
window.addEventListener('resize',scalePreviews);
function updateURL(url){if(location.protocol!=='file:')history.replaceState(null,'',url);}
function selectDirection(direction){clearTimeout(toastTimer);$('#toast').classList.remove('visible');state.direction=direction;state.comparison=false;state.project='all';state.query='';state.filter='all';state.view='ports';state.menuPane='listeners';state.menuOpen=true;const url=new URL(location.href);url.searchParams.set('direction',direction);url.searchParams.set('surface',state.surface);url.searchParams.delete('compare');updateURL(url);render();}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function modal(body,footer=''){const dialog=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-body">${body}</div><div class="dialog-footer">${footer||'<button data-action="close">Close</button>'}</div>`;dialog.showModal();}
function notes(){const d=directions[state.direction];modal(`<div class="eyebrow">${d.number} / DESIGN DIRECTION</div><h2>${d.name}</h2><p>${d.description}</p><p>${d.tradeoff}</p><p>These studies use synthetic data and simulated actions. Project assignment is a proposed capability. No process, network, or cron effects are connected.</p>`);}
function stopDialog(){const p=selected();state.intent='stop';modal(`<div class="eyebrow">SIMULATED CONTROL / NO OS ACCESS</div><h2>Request stop for ${p.name}?</h2><p><span class="mono">${p.process} · PID ${p.pid} · developer</span><br>${p.path}</p><p>In the real app, this affects the process and all its listening ports. Current process identity must match before a signal is sent. Unsaved work may be lost.</p><p>This prototype previews the confirmation only.</p>`,'<button data-action="close">Cancel</button><button class="confirm" data-action="confirm-stop">Simulate stop request</button>');}
function proxyDialog(){const p=selected();modal(`<div class="eyebrow">QUICK PROXY / SIMULATION</div><h2>A local bridge.</h2><p>Forward a new local listener to this endpoint. Real source-IP rules are admission controls, not authentication or encryption.</p><label for="proxy-port">Listen port · this Mac only</label><input id="proxy-port" type="number" min="1" max="65535" value="4000"><label>Target</label><div class="mono" style="font-size:12px">127.0.0.1:${p.port}</div><p>The example starts with IPv4 loopback. LAN exposure would need a separate, deliberate opt-in.</p>`,'<button data-action="close">Cancel</button><button class="continue" data-action="confirm-proxy">Preview local proxy</button>');}
function command(){modal(`<div class="eyebrow">COMMANDS</div><h2>Where do you want to go?</h2><div class="command-options">${sections.map(s=>`<button data-command="${s.key}">${icon(s.icon)}Open ${s.name}<span class="spacer"></span>${icon('arrow')}</button>`).join('')}<button data-command="search">${icon('search')}Find a listener<span class="spacer"></span><kbd>/</kbd></button></div>`);}
function detailDialog(){const p=selected();modal(`<div class="eyebrow">${p.project} / EXAMPLE LISTENER</div><h2>${p.name}</h2><p class="mono">${p.bind}:${p.port}<br>${p.process} · PID ${p.pid} · developer<br>${p.path}</p><p>${p.bind==='0.0.0.0'?'Bound to all IPv4 interfaces. Review routing and firewall rules.':'IPv4 loopback listener. Accepts connections from this Mac.'}</p><p>Resource sample: ${p.cpu}% CPU · ${p.memory} MB. Illustrative only.</p>`,'<button data-action="close">Close</button><button class="continue" data-action="proxy-from-detail">Quick Proxy</button>');}
document.addEventListener('click',event=>{
  const button=event.target.closest('button,a[data-direction],tr[data-port]');if(!button)return;
  if(button.dataset.surface){state.surface=button.dataset.surface;state.query='';state.filter='all';state.project='all';const url=new URL(location.href);url.searchParams.set('surface',state.surface);updateURL(url);render();return;}
  if(button.dataset.menuPane){state.menuPane=button.dataset.menuPane;render();return;}
  if(button.dataset.menuInspect){state.selected=Number(button.dataset.menuInspect);state.surface='window';state.view='ports';state.query='';render();return;}
  if(button.dataset.direction){event.preventDefault();selectDirection(button.dataset.direction);return;}
  if(button.dataset.view){state.view=button.dataset.view;render();return;}
  if(button.dataset.command){$('#modal').close();state.comparison=false;if(button.dataset.command==='search'){state.view='ports';state.menuPane='listeners';render();$('#search')?.focus();}else{state.view=button.dataset.command;if(state.surface==='menubar'){if(state.view==='activity')state.surface='window';else state.menuPane={ports:'listeners',security:'signals',schedules:'next'}[state.view];}render();}return;}
  if(button.dataset.filter){state.filter=button.dataset.filter;render();return;}
  if(button.dataset.project){state.project=button.dataset.project;state.view='ports';render();return;}
  if(button.dataset.port){state.selected=Number(button.dataset.port);render();if(state.surface==='window'&&state.direction==='fieldwork'&&innerWidth<1000)detailDialog();return;}
  if(button.dataset.inspect){state.selected=Number(button.dataset.inspect);state.view='ports';state.filter='all';state.project='all';state.query='';render();return;}
  if(button.dataset.run!==undefined){const job=jobs[Number(button.dataset.run)];modal(`<div class="eyebrow">SIMULATED RUN / NO EXECUTION</div><h2>${job.name}</h2><p>Run Now executes a shell command with your user authority in the real product.</p><p class="mono">${escapeHTML(job.command)}</p><p>No command will execute from this prototype.</p>`,'<button data-action="close">Cancel</button><button class="continue" data-action="simulate-run">Simulate Run Now</button>');return;}
  switch(button.dataset.action){
    case 'menu-toggle':state.menuOpen=!state.menuOpen;render();break;
    case 'open-workspace':state.surface='window';state.view=state.menuPane==='signals'?'security':state.menuPane==='next'?'schedules':'ports';state.query='';{const url=new URL(location.href);url.searchParams.set('surface','window');updateURL(url);}render();break;
    case 'menu-inspect':state.surface='window';state.view='ports';state.query='';render();break;
    case 'compare':state.comparison=true;params.delete('set');{const url=new URL(location.href);url.searchParams.delete('set');url.searchParams.set('compare','1');updateURL(url);}render();break;
    case 'refresh':state.lastCheck='just now';render();toast('Example snapshot refreshed. No system discovery was performed.');break;
    case 'clear':state.query='';state.filter='all';state.project='all';render();break;
    case 'inspector':state.inspector=!state.inspector;render();break;
    case 'density':state.compact=!state.compact;render();break;
    case 'monitor':state.monitor=!state.monitor;render();toast(state.monitor?'Example monitoring resumed.':'Example monitoring paused; last observations retained.');break;
    case 'notes':notes();break;
    case 'command':command();break;
    case 'details':detailDialog();break;
    case 'stop':stopDialog();break;
    case 'proxy':proxyDialog();break;
    case 'proxy-from-detail':$('#modal').close();proxyDialog();break;
    case 'close':$('#modal').close();break;
    case 'confirm-stop':$('#modal').close();toast('Stop request simulated. No signal was sent and no process changed.');break;
    case 'simulate-run':$('#modal').close();toast('Run Now simulated. No shell command executed.');break;
    case 'confirm-proxy':{const input=$('#proxy-port');if(!input.reportValidity())return;const port=Number(input.value);if(!Number.isInteger(port)||port<1||port>65535){input.setCustomValidity('Enter a port from 1 to 65535.');input.reportValidity();input.setCustomValidity('');return;}$('#modal').close();toast(`Preview: 127.0.0.1:${port} → 127.0.0.1:${selected().port}. No listener opened.`);break;}
    case 'copy':{const p=selected();if(navigator.clipboard){navigator.clipboard.writeText(`${p.bind}:${p.port}`).then(()=>toast('Example address copied.'),()=>toast(`Example address: ${p.bind}:${p.port}`));}else toast(`Example address: ${p.bind}:${p.port}`);break;}
  }
});
document.addEventListener('input',event=>{if(event.target.id!=='search')return;const input=event.target;const start=input.selectionStart;state.query=input.value;render();const next=$('#search');next?.focus();try{next?.setSelectionRange(start,start);}catch{/* Search inputs do not expose selection on every browser. */}});
document.addEventListener('keydown',event=>{
  if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if($('#modal').open)$('#modal').close();command();return;}
  if(event.key==='Escape'&&$('#modal').open){$('#modal').close();return;}
  if(event.target.matches('input,textarea')||$('#modal').open)return;
  if(event.key==='/'){event.preventDefault();if(state.comparison)return;state.view='ports';state.menuPane='listeners';render();$('#search')?.focus();}
  if(event.key==='Enter'&&event.target.matches('tr[data-port]')){state.selected=Number(event.target.dataset.port);render();}
  if(['ArrowDown','ArrowUp'].includes(event.key)&&state.view==='ports'&&!state.comparison){const items=visibleRecords();if(!items.length)return;event.preventDefault();const i=items.findIndex(p=>p.port===state.selected);state.selected=items[(i+(event.key==='ArrowDown'?1:-1)+items.length)%items.length].port;render();}
});
render();
